-- Economics Gen2 Season 2 Tour 3. Versioned hard and medium content, 6 easy/10 medium/4 hard.
-- Does not touch legacy Season 1 and aborts if there is learner history on the target season.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='75s';
DO $tour1$
DECLARE
 d jsonb:='[{"ref":"EC9708:G2:EC9708-G2-T3-T-008","d":"hard","sec":135,"k":"C","en":"An economy originally exports $200m of goods and imports $250m. After an appreciation, lower price competitiveness reduces export receipts by $18m while cheaper foreign goods raise import expenditure by $12m. A separate gain in consumer confidence adds $8m to consumption. Assuming other AD components are fixed, what is the change in net exports and the combined change in aggregate demand?","ru":"Экономика первоначально экспортирует товаров на $200 млн и импортирует на $250 млн. После укрепления валюты экспортная выручка падает на $18 млн, а расходы на импорт увеличиваются на $12 млн. Независимый рост уверенности потребителей добавляет $8 млн к потреблению. Остальные компоненты AD неизменны. Как изменятся чистый экспорт и совокупный спрос?","uz":"Iqtisodiyot dastlab $200 mln tovar eksport qiladi va $250 mln import qiladi. Valuta qadrlangach eksport tushumi $18 mln kamayadi, import xarajati $12 mln oshadi. Iste’molchi ishonchining alohida ortishi iste’molga $8 mln qo‘shadi. AD ning boshqa qismlari o‘zgarmaydi. Sof eksport va yalpi talab qanday o‘zgaradi?","options_en":["Net exports −$6m; AD +$8m","Net exports −$30m; AD −$30m","Net exports −$30m; AD −$22m","Net exports +$30m; AD +$38m"],"options_ru":["Чистый экспорт −$6 млн; AD +$8 млн","Чистый экспорт −$30 млн; AD −$30 млн","Чистый экспорт −$30 млн; AD −$22 млн","Чистый экспорт +$30 млн; AD +$38 млн"],"options_uz":["Sof eksport −$6 mln; AD +$8 mln","Sof eksport −$30 mln; AD −$30 mln","Sof eksport −$30 mln; AD −$22 mln","Sof eksport +$30 mln; AD +$38 mln"],"why":["Net exports change by −$18m−$12m=−$30m. Consumption rises $8m, so total AD changes −$30m+$8m=−$22m, other things equal.","Чистый экспорт уменьшается на $18+$12=$30 млн. Потребление прибавляет $8 млн, поэтому изменение AD −$30+$8=−$22 млн.","Sof eksport $18+$12=$30 mln kamayadi. Iste’mol +$8 mln bo‘lgani uchun AD o‘zgarishi −$30+$8=−$22 mln."]},{"ref":"EC9708:G2:EC9708-G2-T3-T-015","d":"hard","sec":135,"k":"D","en":"A country runs a current-account deficit of $12bn for one year, financed wholly by new foreign-currency debt carrying 5% annual interest. Assume the principal remains outstanding and no other changes occur. How much annual interest will this borrowing add from the following year, and why does a deficit-financing strategy of this type create vulnerability?","ru":"Страна имеет годовой дефицит текущего счёта $12 млрд и полностью покрывает его новым валютным долгом под 5% годовых. Основной долг остаётся непогашенным, других изменений нет. Сколько дополнительных годовых процентов появится со следующего года и почему такой способ финансирования создаёт риск?","uz":"Mamlakat bir yil davomida $12 mlrd joriy hisob taqchilligiga ega va uni 5% yillik foizli yangi xorijiy valuta qarzi bilan to‘liq qoplaydi. Asosiy qarz qoladi, boshqa o‘zgarish yo‘q. Keyingi yildan qancha qo‘shimcha yillik foiz kelib chiqadi va bu usul nima uchun xavfli?","options_en":["$60m; debt servicing falls automatically as imports rise","$600m; foreign borrowing always increases export competitiveness","$12bn; borrowing is itself an annual interest payment","$600m; repeated debt financing creates future external servicing obligations"],"options_ru":["$60 млн; обслуживание долга автоматически дешевеет с ростом импорта","$600 млн; внешний долг всегда повышает конкурентоспособность экспорта","$12 млрд; заём равен годовому процентному платежу","$600 млн; повторное долговое финансирование создаёт обязательства по будущим выплатам"],"options_uz":["$60 mln; import oshsa qarz xizmati avtomatik kamayadi","$600 mln; xorijiy qarz doim eksport raqobatini oshiradi","$12 mlrd; qarzning o‘zi yillik foiz","$600 mln; doimiy qarz moliyalashi keyingi tashqi to‘lov majburiyatini yaratadi"],"why":["Annual interest =5%×$12bn=$0.6bn=$600m. The borrowed funds finance the external imbalance now but create future interest and refinancing obligations, especially if repeated.","Годовые проценты 5%×$12 млрд=$0,6 млрд=$600 млн. Долг покрывает текущий дефицит, но создаёт будущие процентные и рефинансовые обязательства.","Yillik foiz 5%×$12 mlrd=$0,6 mlrd=$600 mln. Qarz bugungi taqchillikni qoplaydi, lekin keyingi foiz va qayta moliyalash majburiyatini yaratadi."]},{"ref":"EC9708:G2:EC9708-G2-T3-T-016","d":"hard","sec":135,"k":"A","en":"To reduce demand-pull inflation, a central bank raises interest rates. In an illustrative AD accounting exercise, interest-sensitive household spending falls $16bn and private investment falls $14bn, while government purchases rise independently $10bn. Imports also fall $5bn because domestic spending weakens; exports are unchanged. What is the combined direct change in planned aggregate demand before multiplier effects?","ru":"Чтобы снизить инфляцию спроса, центральный банк повышает ставки. В условном расчёте AD потребительские расходы уменьшаются на $16 млрд, частные инвестиции на $14 млрд, но госзакупки независимо растут на $10 млрд. Импорт сокращается на $5 млрд из-за ослабления внутреннего спроса, экспорт неизменен. Каково общее прямое изменение планируемого AD без мультипликатора?","uz":"Talab inflyatsiyasini kamaytirish uchun markaziy bank stavkani oshiradi. AD hisobining soddalashtirilgan misolida iste’mol $16 mlrd, xususiy investitsiya $14 mlrd kamayadi, davlat xaridi mustaqil $10 mlrd oshadi. Ichki talab pasaygani uchun import $5 mlrd kamayadi, eksport o‘zgarmaydi. Multiplikator ta’sirisiz rejalangan AD bevosita qancha o‘zgaradi?","options_en":["Falls $15bn","Falls $25bn","Falls $45bn","Rises $15bn"],"options_ru":["Падает на $15 млрд","Падает на $25 млрд","Падает на $45 млрд","Растёт на $15 млрд"],"options_uz":["$15 mlrd kamayadi","$25 mlrd kamayadi","$45 mlrd kamayadi","$15 mlrd oshadi"],"why":["AD=C+I+G+X−M, so ΔAD=−16−14+10−(−5)=−15bn. Lower imports partially offset the domestic spending contraction; the fiscal expansion also offsets monetary tightening.","AD=C+I+G+X−M: изменение −16−14+10−(−5)=−$15 млрд. Снижение импорта и рост G частично компенсируют сжатие потребления и инвестиций.","AD=C+I+G+X−M: −16−14+10−(−5)=−$15 mlrd. Importning kamayishi va davlat xaridi o‘sishi ichki xarajat pasayishini qisman qoplaydi."]},{"ref":"EC9708:G2:EC9708-G2-T3-T-019","d":"hard","sec":135,"k":"B","en":"A tariff raises the price of an imported machine component from $20 to $26. A domestic exporter needs three imported components for each finished machine and produces 400 machines, with all other prices and quantities fixed. How much do component costs rise, and which trade-policy concern does this illustrate?","ru":"Пошлина повышает цену импортной детали с $20 до $26. Отечественному экспортёру нужно три такие детали на готовую машину; он выпускает 400 машин. Остальные цены и объёмы неизменны. На сколько растут затраты на детали и какой риск протекционизма это иллюстрирует?","uz":"Boj import detal narxini $20 dan $26 ga oshiradi. Mahalliy eksportchi har bir tayyor mashinaga uchta detal ishlatadi va 400 mashina ishlab chiqaradi. Boshqa narx va hajmlar o‘zgarmaydi. Detal xarajati qancha oshadi va bu himoya siyosatining qaysi xavfini ko‘rsatadi?","options_en":["Costs rise $2,400; tariffs necessarily help all domestic producers","Costs rise $7,200; protection for component producers can weaken downstream exporters","Costs rise $3,600; only final imports become more expensive","Costs rise $7,200; exporter competitiveness necessarily improves"],"options_ru":["Затраты растут на $2 400; пошлины помогают всем местным фирмам","Затраты растут на $7 200; защита производителей деталей может навредить экспортёрам","Затраты растут на $3 600; дорожает только импорт конечных товаров","Затраты растут на $7 200; конкурентоспособность экспорта обязательно повышается"],"options_uz":["Xarajat $2400 oshadi; boj barcha mahalliy firmaga foydali","Xarajat $7200 oshadi; detal ishlab chiqaruvchilarini himoya qilish tayyor mahsulot eksportiga zarar yetkazishi mumkin","Xarajat $3600 oshadi; faqat tayyor import qimmatlashadi","Xarajat $7200 oshadi; eksport raqobati albatta oshadi"],"why":["Every machine uses three components, so 400 machines need 1,200. Each component costs $6 more: 1,200×$6=$7,200. Tariffs can increase input costs for local exporters.","Каждой машине нужны три детали, для 400 машин — 1 200 деталей. Удорожание $6 даёт $7 200 затрат; пошлины на компоненты могут ослабить экспортёров.","400 mashinaga 1200 detal kerak. Har biri $6 qimmatlashadi, jami 1200×$6=$7200. Import detaliga boj mahalliy eksportchi xarajatini oshirishi mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T3-T-009","d":"medium","sec":120,"k":"B","en":"Following a cut in the central-bank policy rate, a household''s variable-rate $200,000 loan falls from 8% to 5% interest, and a firm''s variable-rate $500,000 loan falls from 9% to 7%, with both principals constant. Ignoring fees and compounding, by how much do their combined annual interest expenses decrease, and how might this affect aggregate demand?","ru":"После снижения ключевой ставки процент по кредиту семьи с плавающей ставкой и долгом $200 000 падает с 8% до 5%, а по кредиту фирмы на $500 000 — с 9% до 7%. Основные долги неизменны; комиссии и капитализацию игнорируйте. На сколько суммарно снизятся годовые процентные расходы и как это может повлиять на AD?","uz":"Markaziy bank stavkasi pasaygach oilaning $200 000 o‘zgaruvchan stavkali qarzi foizi 8% dan 5% ga, firmaning $500 000 qarzi foizi 9% dan 7% ga tushadi. Asosiy qarz o‘zgarmaydi, komissiya va murakkab foiz yo‘q. Jami yillik foiz xarajati qanchaga kamayadi va AD ga qanday ta’sir qilishi mumkin?","options_en":["Expenses fall $16,000; AD necessarily falls","Expenses fall $16,000; higher disposable cash flow may support C and I","Expenses fall $6,000; only consumption can change","Expenses fall $21,000; higher debt costs necessarily reduce AD"],"options_ru":["Расходы снижаются на $16 000; AD обязательно падает","Расходы снижаются на $16 000; свободные средства могут поддержать C и I","Расходы снижаются на $6 000; изменится только потребление","Расходы снижаются на $21 000; подорожание долга обязательно уменьшает AD"],"options_uz":["Xarajat $16 000 kamayadi; AD albatta pasayadi","Xarajat $16 000 kamayadi; bo‘sh mablag‘ C va I ni qo‘llashi mumkin","Xarajat $6000 kamayadi; faqat iste’mol o‘zgaradi","Xarajat $21 000 kamayadi; qarz xarajati oshib AD kamayadi"],"why":["Household interest savings=$200,000×3%=$6,000. Firm savings=$500,000×2%=$10,000. Total=$16,000; lower borrowing costs can encourage household spending and private investment.","Семья экономит $200 000×3%=$6 000, фирма $500 000×2%=$10 000. Вместе $16 000; снижение расходов может поддерживать потребление и инвестиции.","Oila $200 000×3%=$6000, firma $500 000×2%=$10 000 tejaydi. Jami $16 000; past foiz xarajati iste’mol va investitsiyani qo‘llashi mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T3-T-010","d":"medium","sec":120,"k":"D","en":"A worker''s nominal salary rises by 3% over a year, but the consumer price index increases from 100 to 108. Using an exact price-adjusted ratio, approximately how much does the worker''s real salary change and why does predictable inflation matter for wage bargaining?","ru":"За год номинальная зарплата работника растёт на 3%, а индекс потребительских цен увеличивается со 100 до 108. По точному отношению индексов как примерно меняется реальная зарплата и почему предсказуемая инфляция важна при обсуждении оплаты?","uz":"Bir yilda ishchining nominal oyligi 3% oshadi, iste’mol narxlari indeksi esa 100 dan 108 ga chiqadi. Aniq narxga tuzatilgan nisbat bo‘yicha real ish haqi qanchaga o‘zgaradi va nega barqaror inflyatsiya ish haqi kelishuvi uchun muhim?","options_en":["Real salary rises 11%, because nominal wages and prices are added","Real salary rises 3%, because prices cannot change purchasing power","Real salary falls exactly 8%, because nominal wages are irrelevant","Real salary falls about 4.63%; unexpected inflation can erode agreed purchasing power"],"options_ru":["Реальная зарплата растёт на 11%, поскольку темпы нужно сложить","Реальная зарплата растёт на 3%, поскольку цены не влияют на покупательную способность","Реальная зарплата падает ровно на 8%, поскольку номинальная зарплата не важна","Реальная зарплата падает примерно на 4,63%; неожиданная инфляция снижает покупательную способность"],"options_uz":["Real ish haqi 11% oshadi, chunki narx va ish haqi qo‘shiladi","Real ish haqi 3% oshadi, chunki narx xarid quvvatiga ta’sir qilmaydi","Real ish haqi aynan 8% tushadi, chunki nominal ish haqi ahamiyatsiz","Real ish haqi taxminan 4,63% tushadi; kutilmagan inflyatsiya kelishilgan xarid quvvatini pasaytiradi"],"why":["Real-wage factor is 1.03/1.08≈0.95370, a fall of 4.63%. Unpredictable inflation makes it harder for workers and firms to agree on the intended real value of nominal pay.","Коэффициент реальной зарплаты 1,03/1,08≈0,95370, снижение на 4,63%. Непредсказуемая инфляция усложняет согласование реальной ценности номинальной оплаты.","Real ish haqi koeffitsienti 1,03/1,08≈0,95370, 4,63% kamayish. Kutilmagan inflyatsiya nominal ish haqining real qiymatini kelishishni qiyinlashtiradi."]},{"ref":"EC9708:G2:EC9708-G2-T3-T-018","d":"medium","sec":130,"k":"C","en":"A training programme raises productivity per worker by 10%, while an independent improvement in labour participation increases the potential workforce by 5%. If capital and working hours are sufficient and both changes apply multiplicatively, by approximately how much could long-run potential output rise, with no immediate AD change?","ru":"Программа обучения повышает производительность на работника на 10%, а независимый рост участия в рынке труда увеличивает потенциальную рабочую силу на 5%. Капитала и рабочего времени достаточно, эффекты перемножаются; немедленных изменений AD нет. На сколько примерно может увеличиться потенциальный долгосрочный выпуск?","uz":"O‘qitish dasturi har ishchi unumdorligini 10% oshiradi, mehnat bozorida qatnashishning mustaqil ortishi potensial ishchi kuchini 5% ko‘paytiradi. Kapital va soatlar yetarli, ta’sirlar ko‘paytiriladi; AD hozir o‘zgarmaydi. Uzoq muddatli potensial mahsulot taxminan qancha o‘sishi mumkin?","options_en":["5%; AD shifts right immediately","10%; labour participation never matters","15.5%; long-run aggregate supply can shift right","50%; potential output rises by the product of percentage changes"],"options_ru":["5%; AD немедленно сдвигается вправо","10%; участие работников не имеет значения","15,5%; долгосрочное совокупное предложение может сдвинуться вправо","50%; потенциальный выпуск равен произведению процентов"],"options_uz":["5%; AD darhol o‘ngga siljiydi","10%; mehnat qatnashuvi ahamiyatsiz","15,5%; uzoq muddatli yalpi taklif o‘ngga siljishi mumkin","50%; potensial mahsulot foizlar ko‘paytmasiga teng"],"why":["With proportional worker productivity and workforce increases, potential output is multiplied by 1.10×1.05=1.155, up 15.5%. This raises productive capacity (LRAS), not necessarily current spending.","Производительность и число работников перемножаются: 1,10×1,05=1,155, потенциальный выпуск +15,5%. Это увеличение долгосрочного предложения, не обязательно текущего спроса.","Unumdorlik va ishchi soni ko‘paytiriladi: 1,10×1,05=1,155, potensial ishlab chiqarish +15,5%. Bu LRAS o‘sishi, joriy AD o‘sishi shart emas."]}]'::jsonb;
 x jsonb; oldq record; new_id bigint; i int; idx int; keytxt text; reftext text; cnt int;
 enwhy text; ruwhy text; uzwhy text; ez int; med int; hard int;
BEGIN
 IF jsonb_array_length(d)<>7 THEN RAISE EXCEPTION 'T3_seven_replacements_required'; END IF;
 IF EXISTS(SELECT 1 FROM public.tour_attempts at JOIN public.tours t ON t.id=at.tour_id WHERE t.subject_id=7 AND t.season_id=2 AND t.tour_no=3)
 THEN RAISE EXCEPTION 'T3_season2_attempts_exist'; END IF;
 SELECT count(*) INTO cnt FROM public.tours t JOIN public.tour_questions l ON l.tour_id=t.id AND l.is_active
 WHERE t.subject_id=7 AND t.season_id=2 AND t.tour_no=3;
 IF cnt<>20 THEN RAISE EXCEPTION 'T3_pool_not20_before: %',cnt; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(d) LOOP
   reftext:=x->>'ref';keytxt:=x->>'k';idx:=ascii(keytxt)-65;
   IF keytxt NOT IN ('A','B','C','D') OR x->>'d' NOT IN ('hard','medium')
      OR jsonb_array_length(x->'options_en')<>4 OR jsonb_array_length(x->'options_ru')<>4
      OR jsonb_array_length(x->'options_uz')<>4
   THEN RAISE EXCEPTION 'T3_invalid_authoring: %',reftext; END IF;
   SELECT q.id,q.subject_id,q.topic,q.subtopic,q.quality_flag,l.tour_id,l.order_no
   INTO STRICT oldq FROM public.questions q JOIN public.tour_questions l ON l.question_id=q.id AND l.is_active
   JOIN public.tours t ON t.id=l.tour_id
   WHERE q.subject_id=7 AND t.subject_id=7 AND t.season_id=2 AND t.tour_no=3 AND q.book_ref=reftext;
   IF EXISTS(SELECT 1 FROM public.tour_answers a WHERE a.question_id=oldq.id)
      OR EXISTS(SELECT 1 FROM public.tour_session_answers_v4 a WHERE a.question_id=oldq.id)
      OR EXISTS(SELECT 1 FROM public.questions q WHERE q.subject_id=7 AND q.book_ref=reftext||'-V2')
   THEN RAISE EXCEPTION 'T3_history_or_duplicate: %',reftext; END IF;
   enwhy:=x->'why'->>0;ruwhy:=x->'why'->>1;uzwhy:=x->'why'->>2;
   INSERT INTO public.questions(subject_id,topic,subtopic,difficulty,qtype,question_text,options_text,correct_answer,explanation,image_url,is_active,
   question_text_ru,question_text_uz,question_text_en,options_text_ru,options_text_uz,options_text_en,explanation_ru,explanation_uz,explanation_en,book_ref,time_limit_sec,quality_flag,quality_status)
   VALUES(oldq.subject_id,oldq.topic,oldq.subtopic,x->>'d','mcq',x->>'en',(x->'options_en')::text,keytxt,
   'Correct: '||(x->'options_en'->>idx)||E'\n'||enwhy,NULL,true,
   x->>'ru',x->>'uz',x->>'en',(x->'options_ru')::text,(x->'options_uz')::text,(x->'options_en')::text,
   'Правильный ответ: '||(x->'options_ru'->>idx)||E'\n'||ruwhy,
   'To‘g‘ri javob: '||(x->'options_uz'->>idx)||E'\n'||uzwhy,
   'Correct answer: '||(x->'options_en'->>idx)||E'\n'||enwhy,
   reftext||'-V2',(x->>'sec')::int,oldq.quality_flag,'published')
   RETURNING id INTO new_id;
   UPDATE public.tour_questions SET is_active=false WHERE tour_id=oldq.tour_id AND question_id=oldq.id AND is_active;
   GET DIAGNOSTICS cnt=ROW_COUNT;
   IF cnt<>1 THEN RAISE EXCEPTION 'T3_old_link_count: %',reftext; END IF;
   INSERT INTO public.tour_questions(tour_id,question_id,order_no,is_active) VALUES(oldq.tour_id,new_id,oldq.order_no,true);
   INSERT INTO public.question_version_links(old_question_id,new_question_id,link_type,reason)
   VALUES(oldq.id,new_id,'replacement','Economics Gen2 season2 Tour3: actual high-order difficulty replacement; old question preserved');
   FOR i IN 0..3 LOOP
     INSERT INTO public.question_answer_diagnostics(question_id,answer_kind,answer_key,answer_value,is_correct,
        mistake_type,weak_skill,feedback_ru,feedback_uz,feedback_en,next_action_ru,next_action_uz,next_action_en,rule_json,quality_status)
     VALUES(new_id,'mcq_option',chr(65+i),NULL,i=idx,
        CASE WHEN i=idx THEN NULL ELSE 'multi_step_economic_reasoning' END,oldq.subtopic,
        'Выбрано: '||(x->'options_ru'->>i)||E'\n'||ruwhy||E'\nОтвет: '||(x->'options_ru'->>idx),
        'Tanlov: '||(x->'options_uz'->>i)||E'\n'||uzwhy||E'\nJavob: '||(x->'options_uz'->>idx),
        'Selected: '||(x->'options_en'->>i)||E'\n'||enwhy||E'\nCorrect: '||(x->'options_en'->>idx),
        CASE WHEN i=idx THEN NULL ELSE 'Перепроверьте каждый шаг.' END,
        CASE WHEN i=idx THEN NULL ELSE 'Har bir bosqichni tekshiring.' END,
        CASE WHEN i=idx THEN NULL ELSE 'Check each step.' END,
        jsonb_build_object('diagnostic_code','EC9708_G2_T3T'||substring(reftext from 'T-([0-9]{3})')||'_V2_'||chr(65+i)),
        'published');
   END LOOP;
 END LOOP;
 UPDATE public.questions q SET difficulty=
  CASE WHEN right(q.book_ref,3) IN ('003','006','007','011','013','017') THEN 'easy' ELSE 'medium' END
 WHERE q.subject_id=7 AND q.book_ref ~ '^EC9708:G2:EC9708-G2-T3-T-[0-9]{3}$'
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d) z WHERE z->>'ref'=q.book_ref);
 GET DIAGNOSTICS cnt=ROW_COUNT;
 IF cnt<>13 THEN RAISE EXCEPTION 'T3_unchanged_expected13: %',cnt; END IF;
 SELECT count(*),count(*) FILTER(WHERE q.difficulty='easy'),
 count(*) FILTER(WHERE q.difficulty='medium'),count(*) FILTER(WHERE q.difficulty='hard')
 INTO cnt,ez,med,hard
 FROM public.tours t JOIN public.tour_questions l ON l.tour_id=t.id AND l.is_active
 JOIN public.questions q ON q.id=l.question_id WHERE t.subject_id=7 AND t.season_id=2 AND t.tour_no=3;
 IF cnt<>20 OR ez<>6 OR med<>10 OR hard<>4 THEN
 RAISE EXCEPTION 'T3_mix_invalid: %,%,%,%',cnt,ez,med,hard; END IF;
END $tour1$;
COMMIT;
